// Generated by setup-steel-tide-pages.mjs
// Fails CI if GitHub Pages paths would break at runtime.
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

function assert(condition, message) {
  if (!condition) {
    console.error('Pages build check failed: ' + message);
    process.exit(1);
  }
}

assert(existsSync('dist/index.html'), 'dist/index.html is missing');
const html = readFileSync('dist/index.html', 'utf8');
assert(html.includes('/steel-tide/assets/'), 'Vite did not build for /steel-tide/');
assert(existsSync('dist/audio/ui-click.m4a'), 'Vite did not copy the public/audio folder');
assert(existsSync('dist/assets'), 'dist/assets is missing');
const jsFiles = readdirSync('dist/assets').filter(name => name.endsWith('.js'));
assert(jsFiles.length > 0, 'No JavaScript bundle was generated');
let bytes = 0;
for (const name of jsFiles) {
  const contents = readFileSync(join('dist/assets', name), 'utf8');
  bytes += contents.length;
  const hasBrokenRootAudio = contents.includes('"/audio/') ||
    contents.includes("'/audio/") ||
    contents.includes(String.fromCharCode(96) + '/audio/');
  assert(!hasBrokenRootAudio, 'Root-relative audio URLs in built JS: ' + name);
}
console.log('Pages build OK: correct /steel-tide/ asset URLs, packaged audio and ' + jsFiles.length + ' JS bundles (' + bytes + ' chars).');
